function last4(text) {
  const s = String(text || '');
  const m = s.match(/(?:ending in|eindigend op|card ending|xxxx|••••)\s*(\d{4})/i);
  if (m) return m[1];
  return '';
}
function amountOf(text) {
  const s = String(text || '');
  const m = s.match(/\u20ac\s*[\d.,]+|\$\s*[\d.,]+|[\d.,]+\s*EUR|[\d.,]+\s*USD/i);
  return m ? m[0] : '';
}
function currencyOf(amount) {
  const a = String(amount || '');
  if (a.indexOf('\u20ac') !== -1 || /EUR/i.test(a)) return 'EUR';
  if (a.indexOf('$') !== -1 || /USD/i.test(a)) return 'USD';
  return '';
}
function isCardAdded(text) {
  return /card added|kaart toegevoegd/i.test(String(text || ''));
}
function isEmptyMsg(j) {
  if (!j) return true;
  return !(j.snippet || j.text || j.textPlain || j.subject || j.from);
}
function row(j, rail) {
  const snippet = j.snippet || j.text || j.textPlain || '';
  const subject = j.subject || '';
  const blob = (subject + ' ' + snippet);
  const date = j.date || j.internalDate || '';
  const from = j.from || '';
  const amt = amountOf(blob);
  const added = isCardAdded(blob);
  let evidence = amt ? 'VERIFIED' : 'UNCERTAIN';
  let note = '';
  if (added && !amt) {
    evidence = 'UNCERTAIN';
    note = 'Card added / kaart toegevoegd is not a charge';
  }
  if (rail === 'Stripe/Paddle' && /onboard|connect your|payout/i.test(blob) && !amt) {
    note = 'Possible seller onboarding, not spend';
  }
  return {
    rail: rail,
    merchant: String(subject).slice(0, 120),
    amount: amt,
    currency: currencyOf(amt),
    cadence: '',
    last_charge: date,
    last4: last4(blob),
    evidence: evidence,
    note: note,
    from: from,
    subject: subject,
    snippet: String(snippet).slice(0, 240)
  };
}
const rails = [
  ['Gmail PayPal', 'PayPal'],
  ['Gmail Apple', 'Apple'],
  ['Gmail Google Play', 'Google Play'],
  ['Gmail Google Pay', 'Google Pay'],
  ['Gmail Stripe/Paddle', 'Stripe/Paddle'],
  ['Gmail SEPA', 'SEPA'],
  ['Gmail Klarna', 'Klarna']
];
const out = [];
for (let r = 0; r < rails.length; r++) {
  const name = rails[r][0];
  const rail = rails[r][1];
  try {
    const items = $(name).all();
    for (let i = 0; i < items.length; i++) {
      if (isEmptyMsg(items[i].json)) continue;
      out.push(row(items[i].json, rail));
    }
  } catch (e) {}
}
return out.map(function (json) { return { json: json }; });
